// core/behaviors/dialog/machine.js
// The framework-NEUTRAL behavior CORE for the configurable pop-up dialog
// (behavior-layer-design.md §1.3 / §5.1). Plain data + one pure transition() fn.
// NO framework import, NO styling, NO DOM — the single source of truth that every
// connector (React/vanilla/Angular) and the company bucket compose against.
//
// Config surface (per the project goal): scroll/no-scroll (`scrollable`),
// resizable + dimensions (`resizable`/`width`/`height`), open/close (the events).
// Per-instance config is merged onto `context` by the shared machine-runtime.

export const dialogMachine = {
  id: "dialog",
  initial: "closed",
  // Config defaults; per-instance config is merged in by the connector/runtime.
  context: { scrollable: true, resizable: false, width: null, height: null },
  states: {
    closed: {
      on: { OPEN: "open" },
    },
    open: {
      on: { CLOSE: "animatingOut" },
      entry: ["trapFocus", "lockScrollIfModal"],
    },
    animatingOut: {
      on: { ANIMATION_END: "closed" },
      exit: ["releaseFocus", "unlockScroll"],
    },
  },
  guards: {
    // Pure guard: resizing is only offered when the instance opted in.
    canResize: (ctx) => ctx.resizable === true,
  },
};

// Pure, deterministic transition — same (state, event, ctx) always yields the same
// result. A table lookup over states[state].on[event.type]; no side effects, no I/O.
// Returns { state, changed, entry, exit }:
//   - state:   the next state name (unchanged if the event is not accepted here)
//   - changed: whether a transition fired
//   - entry:   declarative entry-action names of the target state (for the connector)
//   - exit:    declarative exit-action names of the source state (for the connector)
export function transition(state, event, ctx) {
  const node = dialogMachine.states[state];
  const type = typeof event === "string" ? event : event && event.type;
  const target = node && node.on ? node.on[type] : undefined;

  if (!target) {
    return { state, changed: false, entry: [], exit: [] };
  }

  const exit = node.exit || [];
  const targetNode = dialogMachine.states[target];
  const entry = (targetNode && targetNode.entry) || [];
  return { state: target, changed: true, entry, exit };
}

// Convenience: the initial context with per-instance config applied (pure).
export function initialContext(config = {}) {
  return { ...dialogMachine.context, ...(config || {}) };
}

// company/behaviors/dialog/machine.patch.js
// The COMPANY brand extension of the core dialog FSM (behavior-layer-design.md §3.2 / §5.2).
//
// PURELY ADDITIVE (monotonic). This patch is *merged* onto the core dialogMachine by the
// resolver's applyPatch() (§4.2) — it may ONLY add states / events / context keys. It must
// NOT delete, move, or rebind any core state (closed / open / animatingOut) or any existing
// core transition. The determinism gate (recipe action a7) asserts exactly that.
//
// This file never imports core/behaviors/dialog/machine.js and never mutates it on disk —
// core is read-only to the company bucket. The merge happens at fetch/compose time only.
//
// Patch grammar (consumed by applyPatch, §4.2):
//   context:     { ...newKeys }   — added to core context (additive; no core key removed)
//   addStates:   { <name>: node } — brand-new states only (name must NOT already exist in core)
//   amendStates: { <state>: { on: { <EVENT>: target } } }
//                                  — ADD new events to an existing core state's `on` map.
//                                    May only introduce NEW event keys; rebinding an existing
//                                    core event is a hard error in applyPatch (monotonic rule).

export const patch = {
  // New config key — brand chrome toggle (additive; core context keys untouched).
  context: { brandHeader: true },

  // Brand-new state: the dialog can be MINIMIZED. RESTORE returns to open; CLOSE still
  // funnels through the core animatingOut exit so focus/scroll cleanup stays canonical.
  addStates: {
    minimized: {
      on: { RESTORE: "open", CLOSE: "animatingOut" },
    },
  },

  // Amend the existing core `open` state by ADDING a MINIMIZE event (new event key only).
  // Core's `open` already owns CLOSE → animatingOut; that binding is left exactly as-is.
  amendStates: {
    open: {
      on: { MINIMIZE: "minimized" },
    },
  },
};

export default patch;

