// core/runtime/machine-runtime.js
// The shared, framework-NEUTRAL FSM runtime (behavior-layer-design.md §6.2 risk #1).
// Dependency-free: ZERO imports, ZERO framework code. It drives ANY machine shaped
// { initial, context, states } through a pure transition() fn (see machine.js). Every
// per-framework connector (connect.react/vanilla/angular) layers its own reactivity on
// top of this one interpreter, so React/Bootstrap/Angular never diverge — one source.
//
// Interface (the "useMachineRuntime/send" shape referenced by §5.1):
//   const rt = createMachineRuntime(machine, transition, config)
//   rt.state            -> current state name ("closed" | "open" | "animatingOut" | ...)
//   rt.context          -> merged context (machine defaults <- per-instance config)
//   rt.send(event)      -> apply an event; returns a snapshot {state, context, actions}
//   rt.can(eventType)   -> is `eventType` accepted in the current state?
//   rt.matches(state)   -> is the runtime in `state`?
//   rt.subscribe(fn)    -> observe snapshots (fires immediately, returns unsubscribe)
//   rt.snapshot()       -> {state, context, actions}
//
// `actions` carries the declarative entry/exit action NAMES the machine declared for the
// transition (e.g. "trapFocus"). The runtime is intentionally side-effect-free: it does
// NOT execute them — each connector decides how (focus trap, scroll lock, ...) for its DOM.

export function createMachineRuntime(machine, transition, config = {}) {
  let state = machine.initial;
  let context = { ...(machine.context || {}), ...(config || {}) };
  const listeners = new Set();
  let lastActions = { entry: [], exit: [] };

  const snapshot = () => ({ state, context: { ...context }, actions: { ...lastActions } });
  const notify = () => { for (const fn of listeners) fn(snapshot()); };

  function send(event) {
    const evt = typeof event === "string" ? { type: event } : (event || {});
    const result = transition(state, evt, context) || { state, changed: false };
    lastActions = { entry: result.entry || [], exit: result.exit || [] };
    if (result.changed) {
      state = result.state;
      notify();
    }
    return snapshot();
  }

  const can = (eventType) => {
    const node = machine.states[state];
    return !!(node && node.on && node.on[eventType]);
  };
  const matches = (s) => state === s;

  function subscribe(fn) {
    listeners.add(fn);
    fn(snapshot());
    return () => listeners.delete(fn);
  }

  return {
    get state() { return state; },
    get context() { return context; },
    send, can, matches, subscribe, snapshot,
  };
}

// Alias: connectors that read the runtime as a hook-style factory import this name.
export const useMachineRuntime = createMachineRuntime;

connect.content:
// core/behaviors/dialog/connect.vanilla.js
// CONNECTOR MODULE — vanilla / Bootstrap variant (framework axis).
// behavior-layer-design.md §1.3 (a FIRST-CLASS deliverable, parity with connect.react.tsx).
//
// THIN by design: it owns NO behavior. It imports the framework-NEUTRAL dialog
// machine + pure transition() from ./machine.js and drives them through the shared
// core/runtime/machine-runtime.js (the `useMachineRuntime`/`send` interface). The ONLY
// thing this file adds is the no-framework seam — plain-DOM reactivity (subscribe →
// re-apply attributes) and the vanilla `normalizeProps` mapping (part/data-state/role/aria
// + onClick→addEventListener / className→class / style-object→el.style).
//
// It does NOT import any CSS or token file: design stays orthogonal and meets behavior
// only at the markup contract (parts.md). The prop-getters emit `part="…"` /
// `data-state="…"` exactly so `core/design/dialog.css` can style them with zero coupling.
//
// API parity with the React connector (the cross-framework shape, §5.1):
//   const dialog = useDialog(config)
//   dialog.state                 -> "closed" | "open" | "animatingOut"
//   dialog.isOpen                -> boolean
//   dialog.open() / dialog.close()
//   dialog.getOverlayProps() / getContentProps() / getTitleProps() / getCloseProps()
//   dialog.subscribe(fn)         -> re-render hook (vanilla has no framework scheduler)
//   normalizeProps(el, props)    -> apply a prop-getter bag onto a real DOM element

import { dialogMachine, transition } from "./machine.js";
import { createMachineRuntime } from "../../runtime/machine-runtime.js";

// One title id per dialog instance so `content[aria-labelledby]` → `title[id]` (a11y baseline).
let __dialogTitleSeq = 0;

// ---- vanilla normalizeProps ----
// Per-framework seam (§1.3): React already speaks onClick/className/style, but plain DOM does
// not — so HERE is where the neutral prop bag is translated into real DOM operations. This is
// the one and only vanilla-specific spot; the prop-getters themselves stay framework-neutral.
//
// Mapping rules (mirror the React connector's prop bag keys):
//   part / data-state / role / aria-* / id / type  -> setAttribute / removeAttribute
//   className                                       -> el.className (toggled, not new parts)
//   style (object)                                  -> Object.assign(el.style, …)
//   onClick / onAnimationEnd / on<Event>           -> addEventListener("click"/"animationend"/…)
// Returns the same element for chaining. Re-applying is idempotent for attributes/class/style;
// listeners are de-duplicated per (element, prop-key) so repeated renders don't stack handlers.
const __listenerRegistry = new WeakMap(); // el -> { propKey: {type, fn} }

export function normalizeProps(el, props) {
  if (!el || !props) return el;
  let bound = __listenerRegistry.get(el);
  if (!bound) {
    bound = {};
    __listenerRegistry.set(el, bound);
  }

  for (const [key, value] of Object.entries(props)) {
    if (value === undefined || value === null) {
      // Drop empty values; also clear a stale attribute if one exists (e.g. style/class off).
      if (key === "className") el.removeAttribute("class");
      else if (key !== "style" && !/^on[A-Z]/.test(key)) el.removeAttribute(key);
      else if (key === "style") el.removeAttribute("style");
      continue;
    }

    if (key === "className") {
      el.className = String(value);
      continue;
    }

    if (key === "style" && typeof value === "object") {
      // Reset prior inline style so toggling resizable off doesn't leave stale dimensions.
      el.removeAttribute("style");
      for (const [sk, sv] of Object.entries(value)) {
        if (sv === undefined || sv === null) continue;
        el.style[sk] = sv;
      }
      continue;
    }

    if (/^on[A-Z]/.test(key) && typeof value === "function") {
      // onClick -> "click", onAnimationEnd -> "animationend"
      const type = key.slice(2).toLowerCase();
      const prev = bound[key];
      if (prev) el.removeEventListener(prev.type, prev.fn); // de-dup across re-renders
      el.addEventListener(type, value);
      bound[key] = { type, fn: value };
      continue;
    }

    // Plain attribute (part, data-state, role, aria-modal, aria-labelledby, id, type, …).
    el.setAttribute(key, String(value));
  }
  return el;
}

/**
 * useDialog(config) — the vanilla factory. Same name/shape as the React hook so the
 * cross-framework api stays identical; here it returns a plain object (no React scheduler).
 * The machine + transition are the single source of truth; this factory just wraps the
 * neutral runtime and projects snapshots onto DOM-shaped prop bags.
 *
 * @param {{scrollable?:boolean, resizable?:boolean, width?:string|null, height?:string|null}} config
 */
export function useDialog(config = {}) {
  // The runtime is created ONCE per dialog instance. It merges machine defaults <- per-instance
  // config exactly like the neutral runtime documents (parity with the React connector).
  const rt = createMachineRuntime(dialogMachine, transition, config);
  const titleId = `dialog-title-${++__dialogTitleSeq}`;

  // Execute the machine's DECLARATIVE entry/exit action names against the real DOM. The runtime
  // is side-effect-free and only NAMES actions (trapFocus / lockScrollIfModal / releaseFocus /
  // unlockScroll); the connector decides how. Kept minimal + guarded on `document` for SSR/Node.
  let prevOverflow = "";
  let prevActive = null;
  function runActions(snapshot) {
    if (typeof document === "undefined") return;
    const body = document.body;
    if (snapshot.state === "open") {
      prevActive = document.activeElement;
      prevOverflow = body.style.overflow;
      body.style.overflow = "hidden"; // lockScrollIfModal
    } else {
      // closed / animatingOut: release on the way out (mirrors the React effect cleanup).
      body.style.overflow = prevOverflow; // unlockScroll
      if (prevActive && typeof prevActive.focus === "function") prevActive.focus(); // releaseFocus
      prevActive = null;
    }
  }
  // Side effects run as a runtime subscriber so they fire on every state change, exactly once.
  rt.subscribe(runActions);

  const isOpenNow = () => rt.state === "open";
  const open = () => rt.send("OPEN");
  const close = () => rt.send("CLOSE");

  // pure guard from the core machine — resizing only when the instance opted in.
  const resizable = () => dialogMachine.guards.canResize(rt.context);

  return {
    // Snapshot getters (vanilla reads on demand; subscribe() drives re-renders).
    get state() {
      return rt.state;
    },
    get isOpen() {
      return isOpenNow();
    },
    open,
    close,

    // Re-render seam: vanilla has no framework scheduler, so consumers subscribe and
    // re-apply the prop-getters (and/or toggle visibility) on each snapshot.
    subscribe: (fn) => rt.subscribe(fn),

    // ---- Prop-getters — same contract attributes as the React connector (parts.md) ----

    getOverlayProps: () => ({
      part: "overlay",
      "data-state": rt.state,
      // Click-on-backdrop dismiss is a connector concern (parts.md), not styling.
      onClick: () => close(),
    }),

    getContentProps: () => ({
      part: "content",
      role: "dialog",
      "aria-modal": "true",
      "aria-labelledby": titleId,
      "data-state": rt.state,
      // scroll / no-scroll variant — toggled via class so core/design/dialog.css styles it.
      className: rt.context.scrollable ? "scrollable" : null,
      // resizable + dimensions — inline style ONLY when the instance opted in (canResize).
      style: resizable()
        ? {
            resize: "both",
            overflow: "auto",
            width: rt.context.width ?? undefined,
            height: rt.context.height ?? undefined,
          }
        : null,
      // Drive the FSM's animatingOut → closed leg from the real CSS animation end.
      onAnimationEnd: () => {
        if (rt.matches("animatingOut")) rt.send("ANIMATION_END");
      },
      // Stop backdrop click from bubbling and closing when interacting with content.
      onClick: (e) => e.stopPropagation(),
    }),

    getTitleProps: () => ({
      part: "title",
      id: titleId,
    }),

    getCloseProps: () => ({
      part: "close",
      type: "button",
      "aria-label": "Close dialog",
      onClick: () => close(),
    }),
  };
}

export default useDialog;

css.content:
/* core/design/dialog.css
 * The CORE design layer for the dialog behavior (behavior-layer-design.md §2 / §5.1).
 * TOKEN-ONLY: every value is a design token (--color-semantic-*/--space-*/--radius-*)
 * emitted by Style Dictionary into :root (default + midnight themes). This file targets
 * ONLY the markup contract ([part=...] / [data-state=...] from parts.md) and imports NO
 * behavior/machine/token file — design and behavior stay orthogonal. Re-skins for free
 * under any theme because it never hard-codes a color.
 */

/* ── Overlay: the backdrop ────────────────────────────────────────────────── */
/* A TRUE modal scrim: the connector portals this to document.body, so position:fixed
 * is viewport-relative (it no longer anchors inside an ancestor Card). It must clearly
 * DIM the page behind it in BOTH the default and midnight themes — so the scrim is a
 * neutral DARK token (--color-primitive-gray-900), which reads as a dim in either theme
 * (the semantic background/text tokens flip light↔dark with the theme and would wash out
 * in one of them). Still token-only (a --color-* token) and theme-stable by design. */
[part="overlay"] {
  position: fixed;
  inset: 0;
  z-index: 1000; /* float above page content once portalled to <body> */
  background: var(--color-primitive-gray-900);
  /* token-driven translucency via color-mix: a clearly dimmed (~70%) dark scrim */
  background: color-mix(in srgb, var(--color-primitive-gray-900) 70%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-6);
}

[part="overlay"][data-state="closed"] {
  display: none;
}

/* ── Content: the dialog surface ──────────────────────────────────────────── */
[part="content"] {
  /* ROOT-CAUSE FIX: the absolutely-positioned [part="close"] (top/right) must anchor
   * INSIDE this surface, not at the page corner. position:relative makes the content
   * the containing block for that absolute close — eliminating the detached page-corner
   * 'x' AND the page-scrollbar shift it caused. */
  position: relative;
  background: var(--color-semantic-surface-raised);
  color: var(--color-semantic-text-primary);
  border: 1px solid var(--color-semantic-border-default);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  min-width: 18rem;
  max-width: 90vw;
  box-shadow: 0 10px 30px color-mix(in srgb, var(--color-primitive-gray-900) 35%, transparent);
}

[part="content"][data-state="closed"] {
  display: none;
}

/* ── Scroll / no-scroll variants (config: ctx.scrollable) ─────────────────── */
/* Connector toggles `.scrollable` on [part="content"]. */
[part="content"].scrollable {
  overflow: auto;
  max-height: 80vh;
}

[part="content"]:not(.scrollable) {
  overflow: hidden;
}

/* ── Title ────────────────────────────────────────────────────────────────── */
[part="title"] {
  margin: 0 0 var(--space-4);
  color: var(--color-semantic-text-primary);
  font-size: var(--font-size-xl);
  font-weight: var(--font-weight-semibold);
  line-height: var(--font-line-height-snug);
}

/* ── Close affordance ─────────────────────────────────────────────────────── */
[part="close"] {
  position: absolute;
  top: var(--space-4);
  right: var(--space-4);
  background: transparent;
  border: none;
  color: var(--color-semantic-text-secondary);
  border-radius: var(--radius-md);
  padding: var(--space-1) var(--space-2);
  font-size: var(--font-size-lg);
  cursor: pointer;
}

[part="close"]:hover {
  color: var(--color-semantic-text-primary);
  background: var(--color-semantic-surface-sunken);
}

[part="close"]:focus-visible {
  outline: 2px solid var(--color-semantic-border-focus);
  outline-offset: 2px;
}

/* company/design/dialog.css
 * The COMPANY brand design layer for the dialog (behavior-layer-design.md §3.2 / §5.2).
 *
 * Layered AFTER core/design/dialog.css (the resolver returns css = [ core, company ] in that
 * order — §4.2). It is purely ADDITIVE brand chrome: it styles the company-only `brandHeader`
 * part and the company-only `minimized` data-state, and applies brand accents to core parts via
 * the SAME contract selectors — it never edits the core CSS file.
 *
 * TOKEN-ONLY: every value is a real Style Dictionary token emitted into :root for both the
 * default and midnight themes (--color-semantic-primary-*/--space-*/--radius-*). No color is
 * hard-coded, so the brand chrome re-skins for free under any theme. Imports NO behavior/machine
 * file — design and behavior meet only at the parts.extend.md contract.
 */

/* ── Brand header: the company-only part, layered on top of [part="content"] ──── */
[part="brandHeader"] {
  /* The company demo puts the close button INSIDE this bar. Core now makes [part=content]
   * position:relative, so a bare absolute close would anchor to the content's top-right.
   * Making the brand header its OWN positioning context keeps the close anchored to the
   * HEADER bar (where the brand variant shows it) — additive, core file untouched. */
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--space-3);
  background: var(--color-semantic-primary-default);
  color: var(--color-semantic-primary-contrast);
  padding: var(--space-3) var(--space-6);
  /* sit flush with the rounded top of the core content surface */
  border-top-left-radius: var(--radius-lg);
  border-top-right-radius: var(--radius-lg);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  /* pull out to the content padding edges so the bar spans the surface */
  margin: calc(-1 * var(--space-6)) calc(-1 * var(--space-6)) var(--space-6);
}

[part="brandHeader"]:hover {
  background: var(--color-semantic-primary-hover);
}

/* ── Brand accent on the core close affordance (additive — core file untouched) ── */
[part="content"] [part="brandHeader"] [part="close"] {
  color: var(--color-semantic-primary-contrast);
}

/* ── Minimized: the company-only data-state (collapse to just the brand header) ── */
[part="content"][data-state="minimized"] {
  /* show only the brand header chrome; hide the body until RESTORE */
  overflow: hidden;
  max-height: none;
  padding-bottom: 0;
}

[part="content"][data-state="minimized"] > :not([part="brandHeader"]) {
  display: none;
}
